export const SHULI_DATA: readonly GeneratedShuliData[] = [{"level":"吉","poem":"太极之数","text":"万物开泰的起头数。天地初开、一元复始，凡事从无到有皆由此始。此数之人心志独立、主见极强，不甘居人下，凡事愿自己开局而不愿承旧业；早年多靠己力起家，中年后基础渐固，名利并至。唯独立太过则近于孤高，事事亲力亲为易劳身劳心，若能容人、肯授权，富贵可长保。","keywords":"开创 独立 富贵 名利双收","level_note":"未经外部核验:数理 1 在真实姓名的五格里不可能出现(人格/外格最小为 2)"},{"level":"凶","poem":"两仪之数","text":"混沌未分的分离数。阴阳未定、进退失据，此数之人心思细而志不坚，起念多而落实少，常在两可之间反复，事至中途易生退意；纵有才具亦难聚力于一处，故一生波折多而成就少，家庭亲缘亦每见离散。若能择定一事守到底、少听外言，尚可挽回三分。","keywords":"分离 动摇 意志不坚 劳而无功"},{"level":"大吉","poem":"三才之数","text":"阴阳调和的进取数。天地人三才俱备，智达明敏、才艺兼具，此数之人少年即显颖悟，善解人意而人缘佳，多得长辈提携，故早年即有发达之机；中年名利两全，晚景亦安。唯聪明外露易招妒，须以谦和自守，方能久享。","keywords":"智达 艺能 名利 早发"},{"level":"凶","poem":"凶变之数","text":"破灭衰败的凶数。诸事不顺、万事难成，此数之人纵有才智亦难得施展之地，谋事每于将成之际生变；身体多弱、家庭缘薄，早年常见变故。非无翻身之理，然须以极大的意志与勤勉换取，且宜守成不宜投机、宜专一不宜多头，方能稍避其锋。","keywords":"破灭 辛苦 病弱 万事难成"},{"level":"大吉","poem":"五行之数","text":"阴阳交感的完璧数。五行俱全、刚柔并济，此数之人性温和而有主张，处事圆融不失分寸，故上下咸宜、四方逢源；福禄自来，家门隆昌，寿元亦厚，是数理中最完善的吉数之一。凡事顺遂反易生怠，若能持勤守正，则终身无咎。","keywords":"福禄 长寿 圆满 家门隆昌"},{"level":"吉","poem":"六爻之数","text":"安稳余庆的吉数。天德地祥兼备，此数之人多生于有根基之家，或早年得贵人之荫，故立业不难；性情温厚、能容人，家运隆昌而福泽绵长，晚年尤见余庆。唯顺境久则志易惰，安逸中须留一分进取，否则守得住一时守不住一世。","keywords":"安稳 余庆 富贵 家运隆昌"},{"level":"吉","poem":"精悍之数","text":"刚毅果断的独立数。意志刚强、精力充沛，此数之人认定一事便能排除万难以赴，故常于逆境中反见其能，中年多有成就。然性偏刚硬、不善转圜，与人相处每失之于直，易生嫌隙；若能涵养柔和、听得进异见，则刚而不折，成就更大。","keywords":"刚毅 果断 排除万难 宜养柔和"},{"level":"吉","poem":"八卦之数","text":"意志刚健的进取数。有坚忍不拔之志，能耐劳苦而贯彻始终，此数之人不以聪明取胜，而以恒心取胜，故成功虽迟而稳；中年后渐入佳境，晚运尤佳。唯过刚易折，遇事宜留转圜之地，勿以硬碰硬耗尽元气。","keywords":"坚忍 勤勉 有志竟成"},{"level":"大凶","poem":"大成之数","text":"兴尽凶始的破舟数。才谋虽足而时运不济，此数之人每有大志、亦具能力，然谋事常功败垂成，或成而复败，如破舟入海，力愈用而险愈近；亲缘薄、身多病，中年前后尤须留意。宜守本分、宜依附有力者共事，独当一面则易生凶险。","keywords":"穷乏 逆境 物极必反 大凶"},{"level":"大凶","poem":"终结之数","text":"万事终局的空虚数。天赋虽厚而运途多蹇，此数之人常怀壮志却屡遇障阻，谋事至半而基垮，一生辛劳而所得不称；家庭亦多聚散。非全无成者，然须格外谨慎、格外惜福，且他格若得吉数相扶，尚可减其凶。","keywords":"空虚 终局 破败 万事凋零"},{"level":"大吉","poem":"挽回之数","text":"挽回家运的春成数。草木逢春、枝叶更新，此数之人性稳而有再兴之力，纵出身寒微或家道中落，亦能凭稳健经营重立门户；财源渐进而不骤，是稳中致富之象。晚运尤厚，子孙亦得其荫。","keywords":"再兴 稳健 顺调 富贵荣达"},{"level":"凶","poem":"掘井无泉","text":"意志薄弱的挫折数。家亲缘薄、孤立无援，此数之人常以柔弱之力担过重之事，力不从心而强为之，故中途多挫；心志一摇则前功尽弃，且易因过劳而损身。宜量力而行、宜借外力，不宜逞强独撑。","keywords":"薄弱 孤独 挫折 有志难伸"},{"level":"大吉","poem":"春日牡丹","text":"智略超群的博学数。天赋艺能、多才多艺，此数之人机敏善断，临事能于纷乱中理出头绪，故常为众所倚重；文艺、谋略、辩才皆有可观，中年即见名成。唯才高者每失之于自负，须以忠厚济之，方免招忌。","keywords":"智略 才艺 通达 富贵"},{"level":"大凶","poem":"破兆之数","text":"破兆离散的沉沦数。家庭缘薄、孤独悲哀，此数之人多情而少得回应，用心而少见回报，故内心常郁；事业亦每于顺境中忽生变故，如舟行遇暗礁。宜早立稳固之业、宜广结善缘，勿使孤愤积于胸中。","keywords":"破兆 孤独 沦落 劳而无功"},{"level":"大吉","poem":"福寿之数","text":"福寿圆满的最大吉数。温和恭谦、雅量厚德，此数之人以德服人而非以力压人，故上下和顺、内外咸宜；家庭圆满、事业顺遂、名利福寿俱全，是八十一数中最完满者之一。得此数者尤宜守其厚德，德在则福在。","keywords":"福寿 德望 圆满 家门昌隆"},{"level":"大吉","poem":"厚重之数","text":"厚重载德的兴家数。能得众望、成就大业，此数之人度量宽宏，善纳人言，故人才乐为所用，虽起于微而终能成大器；中年后财官并至，家门光大。唯须防因宽厚而失之于纵，用人仍当有度。","keywords":"厚德 众望 贵人 化险为夷"},{"level":"吉","poem":"刚强之数","text":"刚强突破的权威数。意志坚定、突破万难，此数之人一往无前，遇阻不退，故常能开出别人开不出的局面；然刚愎自用、不纳人言亦是此数之病，与人每因意气而生嫌。若能柔中带刚、听得进逆耳之言，则权威可久。","keywords":"刚强 权威 突破 宜养柔德"},{"level":"吉","poem":"铁镜重磨","text":"有志竟成的铁石数。志向坚固、意志如铁，此数之人一旦立志便不轻改，能于长期困顿中守住方向，故终获权威与成功；财禄自随，晚运尤厚。唯自尊过强、不容侵犯，易与人正面相撞，宜养涵容之量。","keywords":"有志竟成 积小成大 宜戒刚愎"},{"level":"大凶","poem":"多难之数","text":"风云蔽月的破灭数。智谋虽足而遭遇不遇，此数之人常有超群之才，亦每有惊人之举，然时运每与之相违，成败起伏如风云蔽月，忽明忽暗；家庭病弱、刑伤之事亦须留意。宜稳不宜急、宜守不宜攻，且当以他格之吉相济。","keywords":"多难 障碍 病弱 成败起伏"},{"level":"大凶","poem":"屋下藏金","text":"非业破运的空虚数。万事不成、灾难重重，此数之人一生多逢挫折与不测，谋事屡起屡踬，身心俱疲；短命、病弱、破财之象亦时见于此。非无解者，然须以极稳健之姿守成，切忌投机冒进，方能保其身家。","keywords":"破运 空虚 灾难 万事不成"},{"level":"大吉","poem":"明月中天","text":"明月中天的独立权威数。光风霁月、万象昭然，此数之人具首领之资，temperament 明朗而有决断，故能自立门户、渐次上达，终享名利与众望。唯女子得此数者，主见过强而每与人相争，宜以柔济刚。","keywords":"独立 权威 首领运 名利双收"},{"level":"凶","poem":"秋草逢霜","text":"秋草逢霜的薄弱数。志向虽高而力不能副，此数之人内心敏感、外表未必示人，遇挫则伤，故常在半途生退意；身弱、家缘薄亦多见。宜择安稳之业、宜结厚重之友，勿以孤身担大任。","keywords":"秋草逢霜 挫折 孤独 心神过劳"},{"level":"大吉","poem":"壮丽之数","text":"旭日东升的隆昌数。壮丽壮观、旭日东升，此数之人气魄宏大，虽出身微贱亦能凭一己之力扶摇直上，中年即掌大权，是首领之数；财官俱盛，晚景荣华。唯盛极须防骄，女子得此则刚气太重，宜自敛。","keywords":"壮丽 隆昌 由微而显 首领运"},{"level":"大吉","poem":"掘藏得金","text":"家门余庆的金钱数。财源广进、白手成家，此数之人智谋出众而擅理财，能于无中生有、由小积大，故虽起于寒素亦能积成巨富；晚年尤丰，余庆及于子孙。宜守其勤俭本色，勿因既富而奢。","keywords":"掘藏得金 白手成家 财源广进"},{"level":"吉","poem":"荣俊之数","text":"英俊刚毅的资性聪敏数。贤性锐敏、才气奇特，此数之人多具异于常人的见识与手腕，能获大功之运势；然性情时有偏激一方，言语每带讽刺，或有快性怪癖，若不加修养则易与人不和，酿成弊害。能涵养谦和，则可成功。","keywords":"英敏 奇才 宜修涵养 慎防口舌"},{"level":"凶","poem":"变怪之数","text":"变怪奇异的英雄数。波澜重叠、万难袭来，此数之人多具英雄气概与非常才智，然一生起伏极大，或大成或大败，少有平顺者；孤独、刑伤、破产之事亦时见。非常之人行非常之路，若能稳住心性、择正道而行，则波澜之后自有可观。","keywords":"波澜万丈 英雄 成败极端"},{"level":"半吉","poem":"增长之数","text":"欲望无止的中折数。才略过人而易招诽谤，此数之人早熟而发育良好，壮年或中年即得早发之业；然自我过强，每因不肯低头而受攻讦非难，致事业中途生折，晚来难兴。设能自省其身、矫正锐气、待人以诚，仍可避败而自得富荣。","keywords":"中折 招谤 宜自制 半吉"},{"level":"大凶","poem":"阔水浮萍","text":"阔水浮萍的遭难数。虽有豪杰之气魄，却如浮萍无根，一生波澜不断，起伏难安。此数之人多半途遭挫，家亲缘薄、夫妻易离，或有刑伤病弱之忧；纵有一时之成，亦难守久。非无出路，然须择定一处扎稳、少动少迁，方能减其凶。","keywords":"遭难 变动 家属缘薄"},{"level":"大吉","poem":"智谋之数","text":"智谋优秀的财力成大业数。智谋兼具、财力丰厚，此数之人有奇才亦有手腕，能于纷乱中理出机会，故中年即见大业；名利并至而声望不小。唯欲望亦随之而张，贪得则易生非难，女子得此更须防刚气过盛，宜以知足自守。","keywords":"智谋 财力 成大业 忌贪"},{"level":"半吉","poem":"非运之数","text":"非运非命的浮沉数。吉凶难分之数，此数之人一生成败皆极端：得意时如日中天，失意时一落千丈，全看走上哪条路。投机、侥幸之事最易招其凶；若肯守正道、走实业，则浮沉之后仍有可观。是八十一数中最看人自身取舍的一个。","keywords":"浮沉 吉凶难分 宜守正道"},{"level":"大吉","poem":"春日花开","text":"春日花开的智勇得志数。智仁勇三者兼备，此数之人性温和而有统率之才，能得众望而不失分寸，故成事不必强争；中年后名望渐隆，事业与家门俱昌。女子得此亦为吉，是少见的男女皆宜之数。","keywords":"智勇 名望 统率 繁荣"},{"level":"吉","poem":"宝马金鞍","text":"侥幸多望的意外惠泽数。多得贵人提拔，往往在意外中获得成功，如宝马配金鞍，是承他人之力而显达的吉数。此数之人机遇特别好，然福来自外，故须善捉机会亦须惜之；若忘恩背义，则来得快去得也快。","keywords":"侥幸 贵人 意外之福"},{"level":"大吉","poem":"旭日升天","text":"旭日升天的鸾凤相会数。旺盛至极之数，此数之人才德兼备、气魄宏大，能成非常之大业，家门隆昌而名望远播。唯物极必反，盛极须防骄；女子得此则刚气太重，与人相处易生龃龉，宜自敛以柔济之。","keywords":"旺盛 才德 大业 女性嫌刚"},{"level":"大凶","poem":"破家之数","text":"破家亡身的大凶数。灾难重叠、破家之兆，此数之人纵有才具亦难敌其运，谋事屡遭中断，或因一事而累及全局；病弱、刑伤、家散之事皆见于此。若他格得吉数相扶尚可减轻，然终以守成、守分为上，切忌大举大动。","keywords":"破家 灾难 大凶"},{"level":"吉","poem":"温和之数","text":"温良和顺的智达之数。温和平静、智达通畅，此数之人不长于开疆拓土，而长于守成与文事；从艺、从文、从技皆有可观，家庭亦多和顺。若欲强作领袖、硬撑大局，反易生挫；安于己长，则一生平顺可期。","keywords":"温良 智达 宜文 守成"},{"level":"凶","poem":"波澜重叠","text":"波澜重叠的侠义之数。侠义心肠、舍己为人，此数之人重情重义，常为他人奔走而不计得失，故人缘极佳；然自身命运沉浮不定，一生难得安稳，往往成就他人而委屈自己。若能于义气之外多留三分给自己，方免劳而无功。","keywords":"波澜 侠义 沉浮 为人牺牲"},{"level":"吉","poem":"权威显达","text":"权威显达、吉人天相数。天禀温和忠实，独行而有权威，大德奏功之象。此数之人不以巧取胜，而以诚信与德行取得众望，故事业能步步得利，终建大业而享富荣。唯「独行」二字亦是其病：事事自己扛，久之身心俱疲，若能容人、肯授权，则富贵可长保。","keywords":"权威显达 忠实 大德奏功 富贵荣达"},{"level":"吉","poem":"磨铁成针","text":"磨铁成针的意志薄弱数。统率之力不足，然若肯专一磨砺，亦能于一技一艺上成器。此数之人不宜争强、不宜多头，宜择定一门技艺或专业深耕；勤勉可小成，急功则易败。是「守得住就有」的一个数。","keywords":"宜专技 勤勉小成 统率不足"},{"level":"大吉","poem":"富贵荣华","text":"富贵荣华的变化无穷数。权威与财富俱盛，此数之人有雄才亦有雅量，能统众而不失人心，故富贵长寿、家门昌隆，是八十一数中的上上之数。唯其中含有大变之机，盛极须防转折；女子得此则失之于刚，易见孤寡。","keywords":"富贵 权威 长寿 女性嫌孤"},{"level":"半吉","poem":"退安之数","text":"退安则吉、进取则凶数。智谋虽足而德望不称，此数之人常有胆识与手腕，然易生投机之心，一旦冒进则败。宜退守、宜稳健、宜安分守成；若肯以德济才、少走捷径，则可保平安，否则一生浮沉难定。","keywords":"宜退守 投机易败 半吉"},{"level":"大吉","poem":"有德之数","text":"德望高大的有德之数。胆识、德望、才艺俱备，此数之人处事有分寸而待人有诚意，故事业昌隆、名利双收，是纯吉无杂之数。晚运尤佳，福泽亦及子孙。得此数者宜守其厚德，德在则福在。","keywords":"德望 才识 事业昌隆 名利双收"},{"level":"半吉","poem":"寒蝉在柳","text":"寒蝉在柳的博而不精数。多才多艺而失之于杂，此数之人涉猎极广、样样能通，却少有一门做到极处，故常见「什么都会、什么都不精」之叹。宜及早择一专精，广而不深终难成器。⚠️ 此数各派判法不一：有作吉论者、有作凶论者，我们不硬拍，列为半吉并注明分歧。","keywords":"博而不精 宜择一专精 各派分歧"},{"level":"凶","poem":"散财破产","text":"散财破产的雨夜之花数。外表华美而内里空虚，此数之人多有才艺与见识，然意志不坚、用度无节，钱财易聚亦易散；亲缘薄、晚境多凄。若能自律节用、守住一份实业，尚可免于倾覆。","keywords":"散财 外华内虚 意志不坚"},{"level":"大凶","poem":"破家之数","text":"愁眉难展的破家亡身数。诸事不顺、灾祸叠来，此数之人纵有奇才亦每逢逆运，谋事屡遭中断；家庭破散、病弱刑伤之事亦时见。极少数意志超群者能于逆境中转出一片天，然对多数人而言宜守不宜攻、宜静不宜动。","keywords":"破家 灾祸 愁眉难展"},{"level":"吉","poem":"顺风之数","text":"顺风扬帆的新生之数。智谋周备、经纬深奥，此数之人思虑缜密而识见深远，能于大局中看清脉络，故谋事多能顺遂；中年后大志得成，荣华可期。若能戒骄戒躁，则一生少见逆流。","keywords":"顺风 智谋 大志得成 荣华"},{"level":"大凶","poem":"罗网离身","text":"罗网系身的离祖成家数。一生困苦不离身之凶数，此数之人意志若薄，易走入岐途而受缧绁之辱，终身辛苦而多悲；然若能自立志气、以仁义自持，则可离祖成家、于困境中转出新局。是「全看意志」的一个数。","keywords":"罗网系身 困苦 意志薄弱 能自立可转"},{"level":"大吉","poem":"点石成金","text":"点石成金的开花结果数。天赋幸运、贵人自来，此数之人做事往往顺水推舟即成，家门隆昌而子孙亦昌；财帛丰盈，是少见的福厚之数。晚运尤佳，得此数者宜多积德，福可久享。","keywords":"开花结果 天赋幸运 家门隆昌"},{"level":"大吉","poem":"古松立鹤","text":"古松立鹤的德智兼备数。德望与智谋俱高，此数之人可为人师、可为人谋，处事有分寸而言语有分量，故受人尊敬而不树敌；名利虽不必极盛，胜在长久稳当。是最适合走「专业与声望」这条路的数。","keywords":"德智兼备 师范 受人尊敬"},{"level":"半吉","poem":"转变之数","text":"吉凶难分的转变之数。此数含大转折之机，遇吉则大吉、遇凶则大凶，全看他格配合与自身取舍。此数之人一生多逢分水岭，一步走对满盘皆活，一步走错满盘皆输。⚠️ 各派判法分歧极大，我们不硬拍，列为半吉并注明。","keywords":"转变 吉凶难分 各派分歧"},{"level":"半吉","poem":"小舟入海","text":"小舟入海的一成一败数。盛衰交替之数，此数之人常有一次大成，亦常有一次大败，先成后败者尤多；中年前后是关口。宜在得意时预留退路、在失意时守住本分；晚年尤须防倾覆，安分则可保。","keywords":"一成一败 盛衰交替 晚年宜防"},{"level":"半吉","poem":"沉浮之数","text":"盛衰交加的沉浮之数。先盛后衰之象，此数之人早年多顺、名利来得不难，然中年后渐见荣枯无定，若不早作打算，易于晚境落寞。宜守成不宜扩张、宜积蓄不宜挥霍，把前半生的势稳住即是善策。","keywords":"先盛后衰 荣枯无定 宜守成"},{"level":"大吉","poem":"达眼之数","text":"先见之明的理想实现数。有先见之明、精干之才，此数之人意志坚定而善于谋划，能察时世、投机会，故常能于众人未觉时抢先落子；他人以为难事，于其手中往往容易成就，终得名利双全。","keywords":"先见之明 决断 一举成功"},{"level":"半吉","poem":"曲卷难伸","text":"外祥内患的盛衰参半数。外观华美而内里多忧，此数之人表面看去顺遂，实则内有难言之患；前半生顺者后半生多苦，前半生苦者后半生反安。宜早识其虚实，把外面的体面换成里面的实底，方免虚耗。","keywords":"外祥内患 盛衰参半"},{"level":"大凶","poem":"石上栽花","text":"石上栽花的多难数。忧闷困苦、辛苦难成，此数之人纵极尽努力亦每见徒劳，如石上栽花难以生根；亲缘薄、身多病，晚景尤须留意。若他格得强吉相扶尚可减其凶，然大体宜守分、宜安命、勿强求。","keywords":"多难 忧闷 辛苦 难成"},{"level":"凶","poem":"善恶交集","text":"善恶交集的极盛还衰数。外观极美而内里极苦，此数之人常被人羡而自知其难；表面的顺遂之下藏着实际的困顿，且往往在最盛之时忽转急下。唯以坚忍化之：肯吃常人不肯吃的苦、肯守常人不肯守的分，则外美之外亦得内实。","keywords":"外美内苦 极盛还衰 宜坚忍"},{"level":"大凶","poem":"浪里行舟","text":"浪里行舟的事与愿违数。缺乏实行之力，此数之人多有想法而少有落实，事至临门每见迟疑，故一生所愿难偿；晚境尤见困苦。若能补上「做完」这一环、少谋多行，仍可挽回相当一段，否则终是纸上功夫。","keywords":"事与愿违 缺实行力 晚苦"},{"level":"吉","poem":"日照春松","text":"日照春松的寒雪青松数。虽有一时之大难，然天赋幸运，此数之人如寒雪中的青松，越是逆境越显其质；中年前后必逢一次大关，过得去则后运大开，苦尽甘来而享荣华。是「熬得住就赢」的一个数。","keywords":"寒雪青松 苦尽甘来 时来运转"},{"level":"吉","poem":"晚行遇月","text":"晚行遇月的先苦后甘数。浮沉多端，此数之人前半生辛苦、屡遭挫折，家业亦有一度倾颓；然中年后渐入佳境，晚景安泰富裕。得此数者不必急于一时，把前半程当作积累，后半程自有回报。","keywords":"先苦后甘 浮沉 晚年安泰"},{"level":"大凶","poem":"寒蝉悲风","text":"寒蝉悲风的寸进难伸数。缺乏勇气与耐力，此数之人一遇挫折即生退意，故虽有机会亦每每错过；财帛难聚、家业难成，晚景多失意。若能于一处硬撑到底、把「再试一次」变成习惯，方有转机。","keywords":"寸进难伸 失意 缺乏勇气"},{"level":"大凶","poem":"黑暗无光","text":"黑暗无光的动摇不定数。无谋无策、方针不定，此数之人常在几条路之间反复，做一半又改，故一生劳碌而无所成；且易遭刑罚、病患与破财之厄。最要紧的不是选对，而是选定之后不再摇摆。","keywords":"无谋 动摇 方针不定"},{"level":"大吉","poem":"牡丹芙蓉","text":"牡丹芙蓉的名利双收数。名利双收、繁荣富贵，此数之人才华与机遇俱备，事业顺遂而家门昌隆。唯其中含骄慢之机：得意易忘形、顺境易轻人，若不克己自持，内部易生不和而毁于自身。","keywords":"名利双收 宜克己 慎防骄慢"},{"level":"大凶","poem":"基础虚弱","text":"基础虚弱的内外不和数。根基不固、内外失和，此数之人外面看去尚可，内里却经不起考验，一遇风波即见崩落；信用亦随之渐失。宜先补根本、先修人和，把地基打实了再谈发展。","keywords":"基础虚弱 内外不和 信用渐失"},{"level":"大吉","poem":"富贵荣华","text":"万物化育的富贵荣华数。万物化育、诸事顺遂，此数之人身心健全、家庭圆满，事业稳步而少见逆流，子孙亦繁荣，是纯吉之数。得此数者少有大风大浪，宜守其和顺，不必强争。","keywords":"万物化育 富贵荣华 子孙繁荣"},{"level":"大凶","poem":"骨肉分离","text":"骨肉分离的沉滞破败数。灾祸频仍、骨肉分离，此数之人纵勤勉亦难敌其运，谋事屡遭破败，亲缘尤薄；病弱、破财之事亦时见。宜守分安命、少涉险局，且当以他格之吉相济。","keywords":"骨肉分离 沉滞 破败"},{"level":"吉","poem":"巨流归海","text":"巨流归海的家运隆昌数。事事如意、家运隆昌，此数之人如江河归海，行事自有其归处，故富贵长寿而少见坎坷；上下和顺，晚景尤丰。是八十一数中最安稳的吉数之一。","keywords":"巨流归海 家运隆昌 富贵长寿"},{"level":"大凶","poem":"岩头步马","text":"岩头步马的内外不和数。进退失据、内外不和，此数之人如在岩头驱马，前无路而后无援，谋事每于关键处失据；灾祸与损耗亦多。宜大幅收缩、宜稳守本分，不宜同时开多条战线。","keywords":"内外不和 进退失据 灾祸"},{"level":"大吉","poem":"通达之数","text":"通达顺遂的自立成业数。事事通达、得长辈提携，此数之人有独立开创之力，亦能得外助，故家业渐兴而名望渐隆；财帛丰盈，晚运尤佳。得此数者宜把握机遇，勿因安逸而止步。","keywords":"通达 得提携 自立成业"},{"level":"大吉","poem":"顺风扬帆","text":"顺风扬帆的兴家立业数。思虑周密、勤勉务实，此数之人不靠投机而靠积累，故所成虽不迅疾却极稳；创业、发明、经营皆有可观，家业能立而能守。是最适合长线经营的数之一。","keywords":"思虑周密 勤勉 兴家立业"},{"level":"大凶","poem":"非业之数","text":"非业非命的动摇不安数。穷迫困顿、动摇不安，此数之人常处于「明知不对却停不下来」的局面，谋事屡踬而身心俱疲；病弱之忧亦重。宜早断早退、宁可少做，不可硬撑。","keywords":"动摇不安 穷迫 病弱"},{"level":"大凶","poem":"险恶之数","text":"惨淡空虚的险恶之数。空虚惨淡之象，此数之人一生多逢废亡与损耗，纵有一时之得亦难留住；晚景尤见凄凉。唯以极稳健之姿守成，且早为晚年做打算，方能稍避其锋。","keywords":"惨淡 空虚 晚景凄凉"},{"level":"半吉","poem":"石上金花","text":"石上金花的内心劳苦数。外观尚可而内心多苦，此数之人有相当的能力，然缺一股贯彻到底的劲，故常止于半途；若能得贵人相助、或与人合力，则可成事。是「独力难成、合力可成」的一个数。","keywords":"内心劳苦 得贵人则成 半吉"},{"level":"凶","poem":"劳苦之数","text":"先甘后苦的劳苦之数。苦乐参半，此数之人前半生多顺、看似福厚，然中年后渐入辛劳，晚景困苦者多。宜在顺境时即预留后路、节用积蓄，把好日子的余裕留给难走的那一段。","keywords":"先甘后苦 苦乐参半"},{"level":"吉","poem":"志高力微","text":"志高力微的天赋平安数。志向高远而实行之力不足，此数之人常有超出能力的抱负，故大业难成；然天赋平安，衣食无缺、家庭和顺，一生虽无大成亦无大祸。安于此，则是福。","keywords":"志高力微 天赋平安 半吉"},{"level":"大凶","poem":"残菊逢霜","text":"残菊逢霜的沉沦之数。无为坐食、智谋不足，此数之人既少开创之力亦少守成之心，家业渐次消耗而无从补进；晚景尤困。若能勤补其拙、早立一技，尚可自养。","keywords":"沉沦 无为 坐食山空"},{"level":"半吉","poem":"守分之数","text":"守分则吉、进取则凶数。此数之人守则安、动则败：安分守成可保平顺，一旦冒进、扩张、投机则立见挫折。宜稳健、宜依附有力者共事，不宜独当大局。认清这一点，即是此数最大的用处。","keywords":"守分则吉 进取则凶 半吉"},{"level":"大凶","poem":"离散之数","text":"倾覆离散的内外不和数。倾覆离散之象，此数之人前半生多逢破败与骨肉分离，家业与身心俱受折损；然中年后若能立定志气、重整旗鼓，晚年反可转安。是先破后立的一个数。","keywords":"倾覆 离散 晚年或转安"},{"level":"半吉","poem":"半吉半凶","text":"半吉半凶的苦乐参半数。前半生得享福泽者后半生多苦，前半生辛苦者后半生反安，此数之人的关口通常在中年。宜早识其转折之机：得意时不尽用其福，失意时不尽弃其志。","keywords":"半吉半凶 苦乐参半"},{"level":"半吉","poem":"晚苦之数","text":"祸福参半的晚苦之数。中年前尚见发达，才智亦足，然此数之人晚境多困，福泽有其尽头。宜在能积之时多积、在能立之时早立，把中年的余力换成晚年的凭依。","keywords":"祸福参半 晚境困苦"},{"level":"大凶","poem":"云头望月","text":"云头望月的身疲力尽数。穷迫困顿、信用渐失，此数之人纵有才亦难施展，做事每见虎头蛇尾，久之为人所不信；财帛难聚、身心俱疲。宜先重建信用、先做小而实的事，方有转机。","keywords":"身疲力尽 穷迫 信用尽失"},{"level":"大凶","poem":"遁吉之数","text":"辛苦多难的遁吉之数。一生辛苦多难，此数之人若在世事中强争，则处处碰壁；然若早退守静、安于平淡，反能得一份清吉。是八十一数中唯一「退比进好」讲得最明白的一个。","keywords":"辛苦多难 宜早退守静"},{"level":"大吉","poem":"万物回春","text":"万物回春的还本归元数。八十一为极数，还本归元、复归于一，故其吉与「1」同。此数之人尊贵繁荣、名利并至，家门昌隆而福泽绵长，是数理循环的圆满收束。","keywords":"万物回春 还本归元 尊贵繁荣"}];

export const SANCAI_DATA: Record<string, { combo: string; tian_ren: string; ren_di: string; level: string; text: string }> = {"木木木":{"combo":"木木木","tian_ren":"同","ren_di":"同","level":"大吉","text":"上下同气，一路顺生，志向能伸、根基也稳，家门昌隆而身心康泰；唯同气过盛易招妒，宜守谦。"},"木木火":{"combo":"木木火","tian_ren":"同","ren_di":"生","level":"大吉","text":"上得其助、下有出口，事业无碍向上，境遇安泰，是少见的通达之局，晚景亦丰。"},"木木土":{"combo":"木木土","tian_ren":"同","ren_di":"克","level":"大吉","text":"立木于厚土，虽为木克土却是天然之配，根基如磐石，能成事、能守成，名利可期。"},"木木金":{"combo":"木木金","tian_ren":"同","ren_di":"被克","level":"凶","text":"上下同气而根基被金所制，纵肯苦干亦伸展无力，境遇多变、屡受牵掣，心常郁而事常折。"},"木木水":{"combo":"木木水","tian_ren":"同","ren_di":"被生","level":"半吉","text":"上下相亲、根得水润，成功运尚可，唯水多则木浮，根基不实，安定难久，宜择一处扎稳。"},"木火木":{"combo":"木火木","tian_ren":"生","ren_di":"被生","level":"大吉","text":"上下惠助、循环相生，志向顺遂，地位与财帛俱安，子孙亦昌，是极稳的一局。"},"木火火":{"combo":"木火火","tian_ren":"生","ren_di":"同","level":"吉","text":"上助其锐、下亦同热，进取顺当而声势不小，唯火气过旺易生急躁，宜留三分余地。"},"木火土":{"combo":"木火土","tian_ren":"生","ren_di":"生","level":"大吉","text":"木生火、火生土，三才一路顺行，成功与根基俱得，境遇安泰而能久，是最完满的格局之一。"},"木火金":{"combo":"木火金","tian_ren":"生","ren_di":"克","level":"凶","text":"上有所助而根基被克，锐气虽足却落不到实处，屡起屡踬，须防急躁招祸。"},"木火水":{"combo":"木火水","tian_ren":"生","ren_di":"被克","level":"大凶","text":"上下相激，水火不容，成功之途屡遭浇熄，境遇急变，灾厄叠来，宜守拙藏锋。"},"木土木":{"combo":"木土木","tian_ren":"克","ren_di":"被克","level":"大凶","text":"上克其身、下又相侵，两头受制，志难得伸而根基不安，纵勤勉亦多劳少得。"},"木土火":{"combo":"木土火","tian_ren":"克","ren_di":"被生","level":"吉","text":"虽受上克，得下之温助，境遇可稍安，能凭自身沉稳换取一时之成，晚运较前运为佳。"},"木土土":{"combo":"木土土","tian_ren":"克","ren_di":"同","level":"吉","text":"上有所压而根基厚实，虽上进迟缓，胜在守得住，安分经营亦可小成，宜稳不宜躁。"},"木土金":{"combo":"木土金","tian_ren":"克","ren_di":"生","level":"半吉","text":"上克其身，然土能生金，根基有出口，成事费力而终有所得，宜借外力不宜独扛。"},"木土水":{"combo":"木土水","tian_ren":"克","ren_di":"克","level":"大凶","text":"上下俱不相谋，受克于上、散流于下，根基崩落之象，境遇动荡，须防大变。"},"木金木":{"combo":"木金木","tian_ren":"被克","ren_di":"克","level":"大凶","text":"上下皆与己相扞，刚气冲撞，志高而处处受阻，孤立难成，且易伤身。"},"木金火":{"combo":"木金火","tian_ren":"被克","ren_di":"被克","level":"大凶","text":"上被己克、下又克己，前后受敌，纵有才具亦难安其位，多成多败而心力交瘁。"},"木金土":{"combo":"木金土","tian_ren":"被克","ren_di":"被生","level":"凶","text":"因肯努力尚可得相当之成，境遇亦能安定，然成功运劣、难再上层，精神多磨而志难大伸。"},"木金金":{"combo":"木金金","tian_ren":"被克","ren_di":"同","level":"大凶","text":"过于坚刚而被人排斥，陷于不和与孤独，身心过劳，除非意志极坚，否则难展其志。"},"木金水":{"combo":"木金水","tian_ren":"被克","ren_di":"生","level":"大凶","text":"虽勤奋而徒劳少得，常怀烦闷，终因身心过劳而一再失败；纵有一时安定，为时不久。"},"木水木":{"combo":"木水木","tian_ren":"被生","ren_di":"生","level":"大吉","text":"上下相荣，水木相生，成功顺遂而根基稳固，得长上之荫、亦得晚辈之力，福泽绵长。"},"木水火":{"combo":"木水火","tian_ren":"被生","ren_di":"克","level":"凶","text":"上虽相生，下则相激，根基屡受冲动，成而复败，宜守成不宜扩张。"},"木水土":{"combo":"木水土","tian_ren":"被生","ren_di":"被克","level":"凶","text":"得上之润而受下之堵，志向可伸却落不到实处，境遇进退两难，须防积郁成疾。"},"木水金":{"combo":"木水金","tian_ren":"被生","ren_di":"被生","level":"大吉","text":"金水相生、水木相荣，一路托举，成功与根基俱佳，人缘亦厚，是极顺的一局。"},"木水水":{"combo":"木水水","tian_ren":"被生","ren_di":"同","level":"大吉","text":"上下俱得滋养，境遇安泰，才思敏捷而外缘佳，唯水盛则漂，宜择定一事守到底。"},"火木木":{"combo":"火木木","tian_ren":"被生","ren_di":"同","level":"大吉","text":"上下同气而得上之生，志向舒展、根基稳固，成功顺遂，家门昌隆。"},"火木火":{"combo":"火木火","tian_ren":"被生","ren_di":"生","level":"大吉","text":"木火通明，上下相荣，才思与声名俱显，进取顺当，是极通达的一局。"},"火木土":{"combo":"火木土","tian_ren":"被生","ren_di":"克","level":"大吉","text":"上生其身、下有厚土可立，成功与安定兼得，能开局亦能守成，福禄可期。"},"火木金":{"combo":"火木金","tian_ren":"被生","ren_di":"被克","level":"凶","text":"上有所助而根基被克，纵得一时之伸展，终受牵掣，境遇多变而心常不安。"},"火木水":{"combo":"火木水","tian_ren":"被生","ren_di":"被生","level":"吉","text":"上下俱来滋养，根基虽稍浮，成功运佳，能得提携，宜及早扎稳而非四处游走。"},"火火木":{"combo":"火火木","tian_ren":"同","ren_di":"被生","level":"大吉","text":"下生其上、上下同热，志气昂扬，进取神速，唯燃烧过烈须防后继无力。"},"火火火":{"combo":"火火火","tian_ren":"同","ren_di":"同","level":"吉","text":"三火相聚，声势极盛而根基易虚，成败都来得快，宜以稳济之，勿一味求快。"},"火火土":{"combo":"火火土","tian_ren":"同","ren_di":"生","level":"大吉","text":"火盛而能落成实土，热情有着落，成功与根基兼得，名利可望长保。"},"火火金":{"combo":"火火金","tian_ren":"同","ren_di":"克","level":"大凶","text":"上下同热而根基被熔，锐气虽盛却守不住，屡成屡败，且易伤身，宜大幅收敛。"},"火火水":{"combo":"火火水","tian_ren":"同","ren_di":"被克","level":"大凶","text":"上下相激，水火交战，境遇急变而灾厄频仍，纵有才亦难安，宜守静远祸。"},"火土木":{"combo":"火土木","tian_ren":"生","ren_di":"被克","level":"半吉","text":"上生其身、下则相侵，根基屡受动摇，成事须格外费力，宜借稳固之助。"},"火土火":{"combo":"火土火","tian_ren":"生","ren_di":"被生","level":"大吉","text":"火生土、土又得火，上下俱厚，境遇安固，能成事亦能久守，晚景尤佳。"},"火土土":{"combo":"火土土","tian_ren":"生","ren_di":"同","level":"大吉","text":"厚土得火之生，根基极稳，为人踏实而能积，虽升迁不快，胜在少倾覆。"},"火土金":{"combo":"火土金","tian_ren":"生","ren_di":"生","level":"大吉","text":"火生土、土生金，一路顺行，志向能伸、根基能守、所得能积，是最完满的格局之一。"},"火土水":{"combo":"火土水","tian_ren":"生","ren_di":"克","level":"半吉","text":"得上之助而下有流散，根基不牢，成事之后须防守不住，宜早置根本。"},"火金木":{"combo":"火金木","tian_ren":"克","ren_di":"克","level":"大凶","text":"上熔其金、下又相扞，两头受制，刚气无处安放，孤立多败而易伤身。"},"火金火":{"combo":"火金火","tian_ren":"克","ren_di":"被克","level":"大凶","text":"前后皆火，己身受熔，纵有锐气亦被消磨，境遇动荡而心力交瘁。"},"火金土":{"combo":"火金土","tian_ren":"克","ren_di":"被生","level":"半吉","text":"上克其身而下有厚土可依，成事费力却终有所守，宜稳步经营、勿争一时。"},"火金金":{"combo":"火金金","tian_ren":"克","ren_di":"同","level":"大凶","text":"上熔而己身坚刚，内外相扞，与人多不合，纵能成事亦伤和气，孤独易生。"},"火金水":{"combo":"火金水","tian_ren":"克","ren_di":"生","level":"大凶","text":"上克其身、下又外泄，根基与锐气两失，屡起屡落，须防积劳与破财。"},"火水木":{"combo":"火水木","tian_ren":"被克","ren_di":"生","level":"凶","text":"上被下克而根基能生木，己身处两难，成事迂回，宜借下之力而非仰上。"},"火水火":{"combo":"火水火","tian_ren":"被克","ren_di":"克","level":"大凶","text":"水火两头相激，己身居其中而不得安，境遇急变，灾厄频仍，宜守静。"},"火水土":{"combo":"火水土","tian_ren":"被克","ren_di":"被克","level":"大凶","text":"上被己克、下又堵己，前后受敌，志难得伸而根基不安，多劳而少成。"},"火水金":{"combo":"火水金","tian_ren":"被克","ren_di":"被生","level":"大凶","text":"上被己克而下来相生，成功运受阻、根基尚可，宜守本分、积小以成。"},"火水水":{"combo":"火水水","tian_ren":"被克","ren_di":"同","level":"大凶","text":"己身克上而下俱流散，一时可发大势，久则漂零无着，宜及早收拢。"},"土木木":{"combo":"土木木","tian_ren":"被克","ren_di":"同","level":"吉","text":"己身克上而下与己同气，根基尚稳，凭本事能开出局面，唯与长上易生龃龉。"},"土木火":{"combo":"土木火","tian_ren":"被克","ren_di":"生","level":"吉","text":"克上而下有出口，志气能往外使，成事可期，宜以柔济刚、少与上争。"},"土木土":{"combo":"土木土","tian_ren":"被克","ren_di":"克","level":"凶","text":"上下皆土而己身居中相克，四面受阻，纵勤勉亦多劳少得，境遇难安。"},"土木金":{"combo":"土木金","tian_ren":"被克","ren_di":"被克","level":"大凶","text":"上被己克、下又克己，前后受敌，志难伸而根基崩，屡起屡踬，须防重挫。"},"土木水":{"combo":"土木水","tian_ren":"被克","ren_di":"被生","level":"凶","text":"克上而下来相生，根基稍可依，成功运却屡受阻，宜守本分、缓图长远。"},"土火木":{"combo":"土火木","tian_ren":"被生","ren_di":"被生","level":"大吉","text":"上被己生之火所暖、下又生我，一路托举，境遇安固，能逃灾厄而享名利。"},"土火火":{"combo":"土火火","tian_ren":"被生","ren_di":"同","level":"大吉","text":"火盛生土，根基极厚，为人热诚而能落实，成功与安定俱得，福禄可期。"},"土火土":{"combo":"土火土","tian_ren":"被生","ren_di":"生","level":"大吉","text":"上下皆厚而中有火暖，根基笃实，进退有据，虽不迅疾却少倾覆，晚景尤安。"},"土火金":{"combo":"土火金","tian_ren":"被生","ren_di":"克","level":"半吉","text":"上下相济而金泄其气，成事可期却守不住所得，宜节用、宜积，勿贪快。"},"土火水":{"combo":"土火水","tian_ren":"被生","ren_di":"被克","level":"大凶","text":"火居水土之间，上下相激，锐气被浇、根基被冲，境遇急变，宜守静远祸。"},"土土木":{"combo":"土土木","tian_ren":"同","ren_di":"被克","level":"吉","text":"上下同厚而根基被木侵，虽稳而常受牵动，宜守成不宜扩张，安分则无咎。"},"土土火":{"combo":"土土火","tian_ren":"同","ren_di":"被生","level":"大吉","text":"下火生土、上土同气，根基极稳且有暖意，能成事亦能久守，是极安泰的一局。"},"土土土":{"combo":"土土土","tian_ren":"同","ren_di":"同","level":"大吉","text":"三土相叠，笃实厚重，根基如磐，进退有据；唯钝重少变通，宜多纳人言。"},"土土金":{"combo":"土土金","tian_ren":"同","ren_di":"生","level":"大吉","text":"厚土生金，上下俱得其宜，志向能伸、所得能积，名利双收而少倾覆。"},"土土水":{"combo":"土土水","tian_ren":"同","ren_di":"克","level":"凶","text":"上下皆厚而下有流散，根基看似稳实则漏，成事之后须防守不住。"},"土金木":{"combo":"土金木","tian_ren":"生","ren_di":"克","level":"凶","text":"土生其金而下与己扞，锐气有源却无处安放，与下不合，成事而不得人和。"},"土金火":{"combo":"土金火","tian_ren":"生","ren_di":"被克","level":"凶","text":"上生其身而下来熔己，得而复失之象，屡成屡败，宜稳守勿贪。"},"土金土":{"combo":"土金土","tian_ren":"生","ren_di":"被生","level":"大吉","text":"上下皆厚土生金，根基与助力俱足，志向顺遂，所积能守，是极完满的一局。"},"土金金":{"combo":"土金金","tian_ren":"生","ren_di":"同","level":"大吉","text":"土生金而金气坚刚，上下相济，能成大事；唯过刚乏同化，宜养涵容之量。"},"土金水":{"combo":"土金水","tian_ren":"生","ren_di":"生","level":"大吉","text":"土生金、金生水，一路顺行，得上之助而气能外达，成功顺遂、人缘亦厚。"},"土水木":{"combo":"土水木","tian_ren":"克","ren_di":"生","level":"凶","text":"上堵其水而下泄其气，己身两头不得力，志难伸、根基亦浮，多劳少成。"},"土水火":{"combo":"土水火","tian_ren":"克","ren_di":"克","level":"大凶","text":"上堵下激，己身居其间不得安，境遇急变而灾厄频仍，宜守静。"},"土水土":{"combo":"土水土","tian_ren":"克","ren_di":"被克","level":"大凶","text":"上下皆土来堵，水无出路，志向壅塞，境遇困顿，纵有才亦难施展。"},"土水金":{"combo":"土水金","tian_ren":"克","ren_di":"被生","level":"半吉","text":"上有所堵而下来相生，根基尚可依，成功运受阻，宜借下之力、缓图长远。"},"土水水":{"combo":"土水水","tian_ren":"克","ren_di":"同","level":"大凶","text":"上堵而下俱流散，一时可发大势，久则漂零无着，宜及早置一处根本。"},"金木木":{"combo":"金木木","tian_ren":"克","ren_di":"同","level":"凶","text":"上克其身而下与己同气，纵有志亦屡受压制，成事费力，宜守待时。"},"金木火":{"combo":"金木火","tian_ren":"克","ren_di":"生","level":"凶","text":"上克其身、下有出口，志气能往外使，然根基受牵，成而复变，宜稳。"},"金木土":{"combo":"金木土","tian_ren":"克","ren_di":"克","level":"凶","text":"上克其身而己又克下，两头相扞，四面受阻，纵勤勉亦难得安。"},"金木金":{"combo":"金木金","tian_ren":"克","ren_di":"被克","level":"大凶","text":"前后皆金，己身受夹，志向被反复截断，孤立多败且易伤身，宜大幅收敛。"},"金木水":{"combo":"金木水","tian_ren":"克","ren_di":"被生","level":"凶","text":"上克其身而下来相生，根基尚可，成功运劣，宜借外力、勿硬争。"},"金火木":{"combo":"金火木","tian_ren":"被克","ren_di":"被生","level":"凶","text":"己身克上而下与己相生，锐气有源，然与上相扞，成事而不得人和。"},"金火火":{"combo":"金火火","tian_ren":"被克","ren_di":"同","level":"半吉","text":"火盛能克上金，锐气极张，可开局面却难持久，宜以稳济之。"},"金火土":{"combo":"金火土","tian_ren":"被克","ren_di":"生","level":"半吉","text":"克上而下能承其火，根基尚厚，成事可期，唯与长上多有意见相左。"},"金火金":{"combo":"金火金","tian_ren":"被克","ren_di":"克","level":"大凶","text":"前后皆金，己火受夹而屡被扑灭，锐气无处施展，多成多败而心力交瘁。"},"金火水":{"combo":"金火水","tian_ren":"被克","ren_di":"被克","level":"大凶","text":"上被己克、下来克己，前后受敌，境遇急变，灾厄频仍，宜守静远祸。"},"金土木":{"combo":"金土木","tian_ren":"被生","ren_di":"被克","level":"吉","text":"上得己生而下木相侵，根基常受动摇，成事须格外费力，宜择稳而行。"},"金土火":{"combo":"金土火","tian_ren":"被生","ren_di":"被生","level":"大吉","text":"下火生土、土又生上金，一路顺行，根基厚实而助力不断，名利可期。"},"金土土":{"combo":"金土土","tian_ren":"被生","ren_di":"同","level":"大吉","text":"上下皆厚，己身笃实，根基如磐，能成事亦能久守，晚景尤安。"},"金土金":{"combo":"金土金","tian_ren":"被生","ren_di":"生","level":"大吉","text":"上下皆金而己土能生之，助力充沛，所积能守，境遇安固而少倾覆。"},"金土水":{"combo":"金土水","tian_ren":"被生","ren_di":"克","level":"半吉","text":"上得己生而下有流散，助力虽在、根基却漏，成事之后须防守不住。"},"金金木":{"combo":"金金木","tian_ren":"同","ren_di":"克","level":"大凶","text":"上下皆刚而根基被扞，过刚易折，与人多不合，纵能成事亦伤和气而多孤。"},"金金火":{"combo":"金金火","tian_ren":"同","ren_di":"被克","level":"凶","text":"上下同刚而下火来熔，锐气受挫，屡成屡败，宜收敛锋芒、勿争一时。"},"金金土":{"combo":"金金土","tian_ren":"同","ren_di":"被生","level":"大吉","text":"厚土生金，上下皆得其助，根基稳、助力足，志向顺遂而所积能守。"},"金金金":{"combo":"金金金","tian_ren":"同","ren_di":"同","level":"吉","text":"三金相聚，坚刚无比，能排万难而成事；唯乏同化之力，孤高易生，宜养柔和。"},"金金水":{"combo":"金金水","tian_ren":"同","ren_di":"生","level":"吉","text":"上下同气而气能外达，才思敏捷、外缘尚可，唯金水寒凉，宜防内心空虚。"},"金水木":{"combo":"金水木","tian_ren":"生","ren_di":"生","level":"大吉","text":"金生水、水生木，一路顺行，得上之助而下有出口，成功顺遂、根基亦稳。"},"金水火":{"combo":"金水火","tian_ren":"生","ren_di":"克","level":"凶","text":"上得其生而下来相激，根基屡受冲动，成而复败，宜守成勿扩张。"},"金水土":{"combo":"金水土","tian_ren":"生","ren_di":"被克","level":"吉","text":"上生其身而下有所堵，志可伸而落地受阻，宜迂回图之、勿硬顶。"},"金水金":{"combo":"金水金","tian_ren":"生","ren_di":"被生","level":"大吉","text":"前后皆金相生，助力充沛，才思敏捷而人缘佳，境遇安泰，是极顺的一局。"},"金水水":{"combo":"金水水","tian_ren":"生","ren_di":"同","level":"吉","text":"上生而下同流，气盛而根浮，一时可发大势，宜及早扎稳而非四处游走。"},"水木木":{"combo":"水木木","tian_ren":"生","ren_di":"同","level":"大吉","text":"水生木、上下同气，一路托举，志向舒展而根基稳固，得长上之荫，家门昌隆。"},"水木火":{"combo":"水木火","tian_ren":"生","ren_di":"生","level":"大吉","text":"上生其身、下有出口，木火通明，才思与声名俱显，进取顺当，是极通达的一局。"},"水木土":{"combo":"水木土","tian_ren":"生","ren_di":"克","level":"大吉","text":"上来滋养而下有厚土可立，成功与安定兼得，能开局亦能守成，福禄绵长。"},"水木金":{"combo":"水木金","tian_ren":"生","ren_di":"被克","level":"凶","text":"上虽相生而根基被金所制，纵得一时之伸展，终受牵掣，境遇多变而心常郁。"},"水木水":{"combo":"水木水","tian_ren":"生","ren_di":"被生","level":"大吉","text":"上下俱来滋养，才思敏捷、人缘亦厚，成功运佳；唯水多木浮，宜及早扎稳。"},"水火木":{"combo":"水火木","tian_ren":"克","ren_di":"被生","level":"吉","text":"上来相激而下能生我，己身处两难而尚有可依，成事迂回，宜借下之力。"},"水火火":{"combo":"水火火","tian_ren":"克","ren_di":"同","level":"大凶","text":"上水下火两相激荡，己身居其中，境遇急变、灾厄频仍，宜守静远祸。"},"水火土":{"combo":"水火土","tian_ren":"克","ren_di":"生","level":"凶","text":"上克其身而下能承之，锐气虽被浇熄，根基尚可守，宜稳步经营、勿求速成。"},"水火金":{"combo":"水火金","tian_ren":"克","ren_di":"克","level":"大凶","text":"上克其身、下又被己所熔，前后失据，屡起屡落，须防积劳与破财。"},"水火水":{"combo":"水火水","tian_ren":"克","ren_di":"被克","level":"大凶","text":"前后皆水，己火受夹而屡被扑灭，志难得伸，境遇困顿，宜大幅收敛。"},"水土木":{"combo":"水土木","tian_ren":"被克","ren_di":"被克","level":"大凶","text":"己身克上而下木相侵，两头受制，根基崩落之象，纵勤勉亦多劳少得。"},"水土火":{"combo":"水土火","tian_ren":"被克","ren_di":"被生","level":"吉","text":"克上而下火生我，根基得暖，境遇可稍安，凭沉稳能换取一时之成。"},"水土土":{"combo":"水土土","tian_ren":"被克","ren_di":"同","level":"吉","text":"上被己克而下有厚土，根基笃实，虽上进迟缓，胜在守得住，安分则无咎。"},"水土金":{"combo":"水土金","tian_ren":"被克","ren_di":"生","level":"吉","text":"克上而土能生金，根基有出口，成事费力却终有所得，宜借外力不宜独扛。"},"水土水":{"combo":"水土水","tian_ren":"被克","ren_di":"克","level":"大凶","text":"上下皆水而己土居中相堵，四面受冲，根基崩落，境遇动荡，须防大变。"},"水金木":{"combo":"水金木","tian_ren":"被生","ren_di":"克","level":"凶","text":"上得己生而下与己相扞，锐气有源却无处安放，与下不合，成事而不得人和。"},"水金火":{"combo":"水金火","tian_ren":"被生","ren_di":"被克","level":"凶","text":"上得己生而下来熔己，得而复失之象，屡成屡败，宜稳守勿贪。"},"水金土":{"combo":"水金土","tian_ren":"被生","ren_di":"被生","level":"大吉","text":"厚土生金、金又生上，一路顺行，助力充沛而根基稳固，名利可期。"},"水金金":{"combo":"水金金","tian_ren":"被生","ren_di":"同","level":"吉","text":"上得己生而己身坚刚，能排万难以成事；唯乏同化之力，宜养涵容之量。"},"水金水":{"combo":"水金水","tian_ren":"被生","ren_di":"生","level":"大吉","text":"前后皆水而己金能生之，才思敏捷、气能外达，境遇安泰，人缘亦厚。"},"水水木":{"combo":"水水木","tian_ren":"同","ren_di":"生","level":"大吉","text":"上下同流而下有出口，气盛而能落到实处，成功顺遂，晚景亦丰。"},"水水火":{"combo":"水水火","tian_ren":"同","ren_di":"克","level":"大凶","text":"上下俱水而下火受浇，锐气难存，境遇急变，成而复败，宜守静。"},"水水土":{"combo":"水水土","tian_ren":"同","ren_di":"被克","level":"大凶","text":"上下同流而下有所堵，气盛却壅塞不通，志向难伸，宜迂回图之。"},"水水金":{"combo":"水水金","tian_ren":"同","ren_di":"被生","level":"大吉","text":"金生水、上下同气，助力充沛，才思敏捷而人缘佳，境遇安泰，是极顺的一局。"},"水水水":{"combo":"水水水","tian_ren":"同","ren_di":"同","level":"吉","text":"三水相聚，才思与声势俱盛，能取名利；唯流动无着，胜败都极端，宜择一处扎稳。"}};
